var n=`0859-kheer`;var s=`world-0859`;var a=`IN`;var t=`south-asia`;var r=8;var d=59;var o={en:`Kheer`,ua:`Кхір`};var h={en:`Kheer is a India dish made with basmati rice, whole cow milk, pistachio, almond. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кхір, страва кухні країни Індія. Основні складники: рис басматі, цільне коров'яче молоко, фісташка, мигдаль. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`basmati-rice`,120,`g`],[`whole-cow-milk`,950,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 45 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 45 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:45,i:[[`white-granulated-sugar`,125,`g`],[`ground-cardamom`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pistachio`,40,`g`],[`almond`,35,`g`],[`saffron-threads`,1,`pinch`]]}];var m={slug:n,id:s,country:`IN`,region:t,servings:8,minutes:59,title:o,text:h,steps:u};export{a as country,m as default,s as id,d as minutes,t as region,r as servings,n as slug,u as steps,h as text,o as title};